import { startTransition, useEffect, useMemo, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { GitBranch, Search, Sparkles, Tag } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useProjectList } from '@/features/projects/api';
import type { GitBranchInfo, GitHistoryCommit, GitStashInfo, GitWorkingTreeFile } from '@neuralbridge/shared/projects';
import type { GitReviewAgent, GitReviewScope } from '@neuralbridge/shared/git-review';
import type { SmartCommitAgent, SmartCommitReport } from '@neuralbridge/shared/smart-commit';
import { AutomationsPanel } from '@/features/workflows/AutomationsPanel';
import { layoutGitGraph } from './git-graph';

type GitWorkspaceTab = 'overview' | 'automations' | 'review' | 'commit' | 'operations';
const GIT_WORKSPACE_TABS: readonly { id: GitWorkspaceTab; label: string }[] = [
  { id: 'overview', label: 'Visão geral' },
  { id: 'automations', label: 'Automações' },
  { id: 'review', label: 'Revisão IA' },
  { id: 'commit', label: 'Commit e PR' },
  { id: 'operations', label: 'Operações' },
];

function CommitGraph({ commits, selected, onSelect, compact }: { commits: GitHistoryCommit[]; selected: string | null; onSelect: (commit: GitHistoryCommit) => void; compact: boolean }) {
  const graph = layoutGitGraph(commits);
  const rowHeight = compact ? 38 : 52;
  const overscan = 6;
  const [scrollTop, setScrollTop] = useState(0);
  const viewportHeight = 560;
  const start = Math.max(0, Math.floor(scrollTop / rowHeight) - overscan);
  const end = Math.min(commits.length, Math.ceil((scrollTop + viewportHeight) / rowHeight) + overscan);
  const visible = commits.slice(start, end);
  const visibleHashes = new Set(visible.map((commit) => commit.hash));
  return <div data-tour="git-graph" className="relative max-h-[560px] overflow-auto p-1" aria-label="Grafo de commits" onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}>
    <div className="relative pl-10" style={{ height: Math.max(commits.length * rowHeight, rowHeight) }}>
    <svg aria-hidden="true" className="pointer-events-none absolute left-0 top-0 h-full w-10 overflow-visible" viewBox={`0 0 40 ${Math.max(commits.length * rowHeight, rowHeight)}`} preserveAspectRatio="none">
      {graph.edges.filter((edge) => visibleHashes.has(edge.from) || visibleHashes.has(edge.to)).map((edge, index) => {
        const x1 = 20 + edge.fromLane * 8;
        const x2 = 20 + edge.toLane * 8;
        const y1 = edge.row * rowHeight + 17;
        const y2 = edge.toRow * rowHeight + 17;
        return <path key={`${edge.from}-${edge.to}-${index}`} data-from={edge.from} data-to={edge.to} d={`M ${x1} ${y1} C ${x1} ${(y1 + y2) / 2}, ${x2} ${(y1 + y2) / 2}, ${x2} ${y2}`} fill="none" stroke="var(--color-primary)" strokeWidth="1.5" />;
      })}
    </svg>
    {visible.map((commit, offset) => <button type="button" key={commit.hash} data-commit-hash={commit.hash} style={{ top: (start + offset) * rowHeight, height: rowHeight }} onClick={() => onSelect(commit)} className={`absolute left-10 right-1 flex min-h-0 items-start gap-3 rounded-md p-2 text-left hover:bg-accent focus-visible:z-10 ${selected === commit.hash ? 'bg-accent ring-1 ring-primary' : ''}`}>
      <span className="absolute -left-[29px] mt-1 grid size-4 place-items-center rounded-full border-2 border-primary bg-background"><span className="size-1.5 rounded-full bg-primary" /></span>
      <span className="min-w-0 flex-1"><strong className="block truncate text-sm leading-tight">{commit.subject}</strong>{!compact && <span className="text-xs text-muted-foreground">{commit.author} · {new Date(commit.date).toLocaleString()}</span>}</span><code className="text-xs text-primary">{commit.hash.slice(0, 8)}</code>
    </button>)}
    {graph.danglingParents.length > 0 && <p className="mt-2 text-xs text-muted-foreground">A continuidade segue para uma página anterior do histórico.</p>}
    </div>
  </div>;
}

function GitOperationsPanel({ projectId, workingTree, selectedCommit, selectedParents, onRefresh }: { projectId: string; workingTree: GitWorkingTreeFile[]; selectedCommit: string | null; selectedParents: number; onRefresh: () => void }) {
  const queryClient = useQueryClient();
  const [branchName, setBranchName] = useState('');
  const [renameFrom, setRenameFrom] = useState('');
  const [renameTo, setRenameTo] = useState('');
  const [stashMessage, setStashMessage] = useState('');
  const [includeUntracked, setIncludeUntracked] = useState(false);
  const [commitMessage, setCommitMessage] = useState('');
  const [mainline, setMainline] = useState('1');
  const [pushRemote, setPushRemote] = useState('');
  const branches = useQuery({ queryKey: ['git-branches', projectId], queryFn: () => window.neuralbridge.projects.branches(projectId) });
  const stashes = useQuery({ queryKey: ['git-stashes', projectId], queryFn: () => window.neuralbridge.projects.stashes(projectId) });
  const syncStatus = useQuery({ queryKey: ['git-sync-status', projectId], queryFn: () => window.neuralbridge.projects.syncStatus(projectId), refetchInterval: 5000 });
  const refresh = () => { void queryClient.invalidateQueries({ queryKey: ['git-branches', projectId] }); void queryClient.invalidateQueries({ queryKey: ['git-stashes', projectId] }); void queryClient.invalidateQueries({ queryKey: ['git-working-tree', projectId] }); void queryClient.invalidateQueries({ queryKey: ['git-sync-status', projectId] }); onRefresh(); };
  const write = async (operation: string, parameters: Record<string, string | string[]>, action: (token: string) => Promise<unknown>) => { const grant = await window.neuralbridge.projects.authorize(projectId, operation, parameters); await action(grant.token); refresh(); };
  const createBranch = useMutation({ mutationFn: async () => { const name = branchName.trim(); if (!name) throw new Error('Informe o nome da branch.'); await write('branch-create', { name }, (token) => window.neuralbridge.projects.createBranch(projectId, name, token)); }, onSuccess: () => setBranchName('') });
  const switchBranch = useMutation({ mutationFn: async (name: string) => { if (!window.confirm(`Alternar para ${name}? Alterações não staged devem estar salvas.`)) throw new Error('cancelled'); await write('branch-switch', { name }, (token) => window.neuralbridge.projects.switchBranch(projectId, name, token)); } });
  const renameBranch = useMutation({ mutationFn: async () => { const oldName = renameFrom.trim(); const newName = renameTo.trim(); if (!oldName || !newName) throw new Error('Informe a branch atual e o novo nome.'); if (!window.confirm(`Renomear ${oldName} para ${newName}?`)) throw new Error('cancelled'); await write('branch-rename', { oldName, newName }, (token) => window.neuralbridge.projects.renameBranch(projectId, oldName, newName, token)); }, onSuccess: () => { setRenameFrom(''); setRenameTo(''); } });
  const deleteBranch = useMutation({ mutationFn: async (name: string) => { if (!window.confirm(`Excluir ${name}? A operação não é permitida para a branch atual ou usada por outra worktree.`)) throw new Error('cancelled'); await write('branch-delete', { name }, (token) => window.neuralbridge.projects.deleteBranch(projectId, name, token)); } });
  const createStash = useMutation({ mutationFn: async () => { const message = stashMessage.trim(); if (!message) throw new Error('Informe uma descrição para o stash.'); if (!window.confirm('Guardar as alterações atuais no stash?')) throw new Error('cancelled'); await write('stash', { message, includeUntracked: String(includeUntracked) }, (token) => window.neuralbridge.projects.createStash(projectId, message, includeUntracked, token)); }, onSuccess: () => setStashMessage('') });
  const stashAction = useMutation({ mutationFn: async ({ ref, pop }: { ref: string; pop: boolean }) => { if (!window.confirm(`${pop ? 'Aplicar e remover' : 'Aplicar'} ${ref}? Conflitos serão preservados para resolução manual.`)) throw new Error('cancelled'); await write('stash', { ref, pop: String(pop) }, (token) => window.neuralbridge.projects.applyStash(projectId, ref, pop, token)); } });
  const dropStash = useMutation({ mutationFn: async (ref: string) => { if (!window.confirm(`Excluir ${ref}?`)) throw new Error('cancelled'); await write('stash', { ref }, (token) => window.neuralbridge.projects.dropStash(projectId, ref, token)); } });
  const commit = useMutation({ mutationFn: async () => { const message = commitMessage.trim(); if (!message) throw new Error('Informe a mensagem do commit.'); if (!workingTree.some((file) => file.staged)) throw new Error('Prepare ao menos um arquivo antes do commit.'); if (!window.confirm('Criar o commit com os arquivos staged?')) throw new Error('cancelled'); await write('commit', { message }, (token) => window.neuralbridge.projects.commit(projectId, message, token)); }, onSuccess: () => setCommitMessage('') });
  const push = useMutation({ mutationFn: async () => { const status = syncStatus.data; const remote = pushRemote || status?.remote || status?.remotes[0] || ''; if (!status?.branch || !remote) throw new Error('Configure um remoto Git antes de subir commits.'); if (!window.confirm(`${status.upstream ? `Subir ${status.ahead} commit(s)` : 'Publicar esta branch'} para ${remote}?`)) throw new Error('cancelled'); await write('push', { remote }, (token) => window.neuralbridge.projects.push(projectId, remote, token)); } });
  const operation = useQuery({ queryKey: ['git-operation-state', projectId], queryFn: () => window.neuralbridge.projects.operationState(projectId), refetchInterval: 1500 });
  const runHistoryAction = useMutation({ mutationFn: async ({ kind }: { kind: 'revert' | 'cherry-pick' }) => { if (!selectedCommit) throw new Error('Selecione um commit no grafo.'); const mainlineNumber = Number(mainline); if (selectedParents > 1 && (!Number.isInteger(mainlineNumber) || mainlineNumber < 1 || mainlineNumber > selectedParents)) throw new Error(`Informe uma mainline entre 1 e ${selectedParents}.`); const mainlineValue: number | undefined = selectedParents > 1 ? mainlineNumber : undefined; if (!window.confirm(`${kind === 'revert' ? 'Reverter' : 'Aplicar'} o commit ${selectedCommit.slice(0, 8)}${mainlineValue ? ` usando mainline ${mainlineValue}` : ''}?`)) throw new Error('cancelled'); await write(kind, { commit: selectedCommit, mainline: String(mainlineValue ?? '') }, (token) => kind === 'revert' ? window.neuralbridge.projects.revert(projectId, selectedCommit, mainlineValue, token) : window.neuralbridge.projects.cherryPick(projectId, selectedCommit, mainlineValue, token)); } });
  const resolve = useMutation({ mutationFn: async (action: 'continue' | 'abort') => { const operationName = operation.data?.operation; if (!operationName) throw new Error('Nenhuma operação pendente.'); if (!window.confirm(`${action === 'abort' ? 'Abortar' : 'Continuar'} a operação ${operationName}?`)) throw new Error('cancelled'); await write(operationName, { action }, (token) => window.neuralbridge.projects.resolveOperation(projectId, operationName, action, token)); } });
  const error = [createBranch, switchBranch, renameBranch, deleteBranch, createStash, stashAction, dropStash, commit, push, runHistoryAction, resolve].find((mutation) => mutation.isError)?.error;
  return <section data-tour="git-actions" className="mx-auto mt-4 grid max-w-[1600px] gap-4 lg:grid-cols-3" aria-label="Operações Git">
    <div className="sg-panel rounded-xl p-4"><h2 className="font-medium">Sincronização</h2><p className="mt-1 text-xs text-muted-foreground">Aqui você vê o commit local pendente e decide quando subir para o remoto.</p>{syncStatus.isPending ? <p role="status" className="mt-3 text-xs text-muted-foreground">Consultando o remoto configurado…</p> : syncStatus.data ? <><dl className="mt-3 grid grid-cols-2 gap-2 text-xs"><div><dt className="text-muted-foreground">Branch</dt><dd className="font-medium">{syncStatus.data.branch ?? 'detached HEAD'}</dd></div><div><dt className="text-muted-foreground">Upstream</dt><dd className="font-medium">{syncStatus.data.upstream ?? 'não configurado'}</dd></div><div><dt className="text-muted-foreground">À frente</dt><dd className="font-medium">{syncStatus.data.ahead}</dd></div><div><dt className="text-muted-foreground">Atrás</dt><dd className="font-medium">{syncStatus.data.behind}</dd></div></dl>{syncStatus.data.pending.length ? <ul aria-label="Commits pendentes para subir" className="mt-3 max-h-32 space-y-1 overflow-y-auto text-xs">{syncStatus.data.pending.map((commit) => <li key={commit.hash} className="flex gap-2"><code className="text-primary">{commit.hash.slice(0, 8)}</code><span className="min-w-0 truncate">{commit.subject}</span></li>)}</ul> : <p className="mt-3 text-xs text-muted-foreground">Nenhum commit local pendente neste upstream.</p>}{syncStatus.data.remotes.length > 1 && <label className="mt-3 block text-xs text-muted-foreground">Remoto<select aria-label="Remoto para subir" className="mt-1 h-8 w-full rounded-md border bg-background px-2 text-sm text-foreground" value={pushRemote || syncStatus.data.remote || syncStatus.data.remotes[0] || ''} onChange={(event) => setPushRemote(event.target.value)}>{syncStatus.data.remotes.map((remote) => <option key={remote} value={remote}>{remote}</option>)}</select></label>}<Button className="mt-3" size="sm" onClick={() => push.mutate()} disabled={push.isPending || !syncStatus.data.branch || !syncStatus.data.remotes.length}>{syncStatus.data.upstream ? 'Subir commits' : 'Publicar branch'}</Button></> : syncStatus.isError ? <p role="alert" className="mt-3 text-xs text-destructive">Não foi possível ler o estado de sincronização.</p> : null}</div>
    <div className="sg-panel rounded-xl p-4"><h2 className="font-medium">Branches</h2><p className="mt-1 text-xs text-muted-foreground">Operações protegidas pelo estado atual do working tree e das worktrees.</p><div className="mt-3 flex gap-2"><input aria-label="Nova branch" className="h-9 min-w-0 flex-1 rounded-md border bg-background px-2 text-sm" placeholder="nome-da-branch" value={branchName} onChange={(event) => setBranchName(event.target.value)} /><Button size="sm" onClick={() => createBranch.mutate()} disabled={createBranch.isPending}>Criar</Button></div><ul className="mt-3 space-y-2 text-sm">{branches.data?.map((branch: GitBranchInfo) => <li key={`${branch.remote ? 'remote' : 'local'}-${branch.name}`} className="flex items-center gap-2"><GitBranch className="size-3.5 text-primary" /><span className="min-w-0 flex-1 truncate">{branch.name}{branch.current ? ' · atual' : ''}{branch.worktree ? ' · worktree' : ''}</span>{!branch.remote && !branch.current && !branch.worktree && <><Button size="sm" variant="outline" className="h-7 px-2 text-[11px]" onClick={() => switchBranch.mutate(branch.name)} disabled={switchBranch.isPending}>Alternar</Button><Button size="sm" variant="ghost" className="h-7 px-2 text-[11px]" onClick={() => deleteBranch.mutate(branch.name)} disabled={deleteBranch.isPending}>Excluir</Button></>}</li>)}{!branches.isPending && !branches.data?.length && <li className="text-xs text-muted-foreground">Nenhuma branch local encontrada.</li>}</ul><div className="mt-3 grid gap-2 sm:grid-cols-2"><input aria-label="Branch a renomear" className="h-8 rounded-md border bg-background px-2 text-xs" placeholder="branch atual" value={renameFrom} onChange={(event) => setRenameFrom(event.target.value)} /><input aria-label="Novo nome da branch" className="h-8 rounded-md border bg-background px-2 text-xs" placeholder="novo nome" value={renameTo} onChange={(event) => setRenameTo(event.target.value)} /></div><Button className="mt-2" size="sm" variant="outline" onClick={() => renameBranch.mutate()} disabled={renameBranch.isPending}>Renomear branch</Button></div>
    <div className="sg-panel rounded-xl p-4"><h2 className="font-medium">Stash</h2><p className="mt-1 text-xs text-muted-foreground">Preserva a entrada ao aplicar; conflitos permanecem visíveis no working tree.</p><div className="mt-3 flex gap-2"><input aria-label="Descrição do stash" className="h-9 min-w-0 flex-1 rounded-md border bg-background px-2 text-sm" placeholder="descrição" value={stashMessage} onChange={(event) => setStashMessage(event.target.value)} /><Button size="sm" onClick={() => createStash.mutate()} disabled={createStash.isPending}>Guardar</Button></div><label className="mt-2 flex items-center gap-2 text-xs text-muted-foreground"><input type="checkbox" checked={includeUntracked} onChange={(event) => setIncludeUntracked(event.target.checked)} /> incluir não rastreados</label><ul className="mt-3 space-y-2 text-xs">{stashes.data?.map((stash: GitStashInfo) => <li key={stash.ref} className="flex items-center gap-2"><code className="text-primary">{stash.ref}</code><span className="min-w-0 flex-1 truncate">{stash.message}</span><Button size="sm" variant="outline" className="h-7 px-2 text-[11px]" onClick={() => stashAction.mutate({ ref: stash.ref, pop: false })}>Aplicar</Button><Button size="sm" variant="outline" className="h-7 px-2 text-[11px]" onClick={() => stashAction.mutate({ ref: stash.ref, pop: true })}>Pop</Button><Button size="sm" variant="ghost" className="h-7 px-2 text-[11px]" onClick={() => dropStash.mutate(stash.ref)}>Excluir</Button></li>)}{!stashes.isPending && !stashes.data?.length && <li className="text-xs text-muted-foreground">Nenhum stash salvo.</li>}</ul></div>
    <div className="sg-panel rounded-xl p-4"><h2 className="font-medium">Commit e recuperação</h2><p className="mt-1 text-xs text-muted-foreground">Somente arquivos staged serão incluídos. Ações de histórico exigem um commit selecionado.</p><p className="mt-3 text-xs text-muted-foreground">{workingTree.filter((file) => file.staged).length} arquivo(s) staged</p><textarea aria-label="Mensagem do commit" className="mt-2 min-h-20 w-full rounded-md border bg-background p-2 text-sm" placeholder="Descreva a mudança" value={commitMessage} onChange={(event) => setCommitMessage(event.target.value)} /><Button className="mt-2" onClick={() => commit.mutate()} disabled={commit.isPending || !workingTree.some((file) => file.staged)}>Criar commit</Button><div className="mt-4 border-t pt-3"><p className="text-xs text-muted-foreground">Commit selecionado: {selectedCommit ? selectedCommit.slice(0, 8) : 'nenhum'}</p>{selectedParents > 1 && <label className="mt-2 block text-xs text-muted-foreground">Mainline do merge<input aria-label="Mainline do merge" inputMode="numeric" min="1" max={selectedParents} className="mt-1 h-8 w-full rounded-md border bg-background px-2 text-sm" value={mainline} onChange={(event) => setMainline(event.target.value)} /><span className="mt-1 block">Escolha o parent sem assumir uma direção.</span></label>}<div className="mt-2 flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => runHistoryAction.mutate({ kind: 'revert' })} disabled={!selectedCommit || runHistoryAction.isPending}>Reverter</Button><Button size="sm" variant="outline" onClick={() => runHistoryAction.mutate({ kind: 'cherry-pick' })} disabled={!selectedCommit || runHistoryAction.isPending}>Cherry-pick</Button></div></div>{operation.data?.operation && <div className="mt-4 rounded-md border border-warning/40 bg-warning/10 p-3"><h3 className="text-sm font-medium">Operação em andamento: {operation.data.operation}</h3><p className="mt-1 text-xs">{operation.data.conflicts.length ? `Conflitos: ${operation.data.conflicts.join(', ')}` : 'Resolva os arquivos e atualize o estado.'}</p><div className="mt-2 flex gap-2"><Button size="sm" onClick={() => resolve.mutate('continue')} disabled={resolve.isPending || operation.data.conflicts.length > 0}>Continuar</Button><Button size="sm" variant="outline" onClick={() => resolve.mutate('abort')} disabled={resolve.isPending}>Abortar</Button></div></div>}{error instanceof Error && <p role="alert" className="mt-3 text-xs text-destructive">{error.message}</p>}</div>
  </section>;
}

function GitReviewPanel({ projectId, selectedCommit, compareLeft, compareRight, onOpenDiff }: { projectId: string; selectedCommit: string | null; compareLeft: string; compareRight: string; onOpenDiff: (path: string, scope: GitReviewScope) => void }) {
  const queryClient = useQueryClient();
  const [agent, setAgent] = useState<GitReviewAgent>('auto');
  const [taskId, setTaskId] = useState<string | null>(null);
  const [scope, setScope] = useState<GitReviewScope>({ kind: 'working-tree' });
  const [appliedFinding, setAppliedFinding] = useState<string | null>(null);
  const start = useMutation({
    mutationFn: async (nextScope: GitReviewScope) => {
      setScope(nextScope);
      return window.neuralbridge.tasks.startGitReview({ projectId, agent, scope: nextScope });
    },
    onSuccess: (result) => setTaskId(result.id),
  });
  const applyPatch = useMutation({
    mutationFn: async ({ findingId, patch }: { findingId: string; patch: string }) => {
      if (!window.confirm('Aplicar esta sugestão no working tree? Nenhum commit será criado; confirme apenas se a pré-visualização foi revisada.')) throw new Error('cancelled');
      const grant = await window.neuralbridge.projects.authorizePatch(projectId, patch);
      await window.neuralbridge.projects.applyPatch(projectId, patch, grant.token);
      return findingId;
    },
    onSuccess: (findingId) => {
      setAppliedFinding(findingId);
      void queryClient.invalidateQueries({ queryKey: ['git-working-tree', projectId] });
      void queryClient.invalidateQueries({ queryKey: ['git-intelligence-diff', projectId] });
    },
  });
  const task = useQuery({ queryKey: ['git-review-task', taskId], queryFn: () => window.neuralbridge.tasks.get(taskId as string), enabled: Boolean(taskId), refetchInterval: taskId ? 1000 : false });
  const report = useQuery({ queryKey: ['git-review-report', taskId], queryFn: () => window.neuralbridge.tasks.gitReview(taskId as string), enabled: Boolean(taskId), refetchInterval: task.data?.status === 'completed' || task.data?.status === 'failed' || task.data?.status === 'cancelled' ? false : 1000 });
  const error = start.error ?? task.error ?? report.error;
  const scopeLabel = scope.kind === 'working-tree' ? 'working tree' : scope.kind === 'commit' ? `commit ${scope.commit?.slice(0, 8)}` : `${scope.base}…${scope.head}`;
  return <section className="mx-auto mt-4 max-w-[1600px] sg-panel rounded-xl p-4" aria-label="Revisão de código por IA">
    <div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-medium">AI Code Review</h2><p className="mt-1 max-w-2xl text-xs text-muted-foreground">Revisão somente leitura com evidências no diff real. Código, comentários e contexto RAG são tratados como dados não confiáveis.</p></div><label className="text-xs text-muted-foreground">Agente<select aria-label="Agente da revisão Git" className="ml-2 h-8 rounded-md border bg-background px-2 text-xs" value={agent} onChange={(event) => setAgent(event.target.value as GitReviewAgent)} disabled={start.isPending}><option value="auto">Automático</option><option value="claude">Claude Code</option><option value="codex">Codex CLI</option></select></label></div>
    <div className="mt-4 flex flex-wrap gap-2"><Button size="sm" onClick={() => start.mutate({ kind: 'working-tree' })} disabled={start.isPending}>Revisar working tree</Button><Button size="sm" variant="outline" onClick={() => selectedCommit && start.mutate({ kind: 'commit', commit: selectedCommit })} disabled={!selectedCommit || start.isPending}>Revisar commit selecionado</Button><Button size="sm" variant="outline" onClick={() => compareLeft && compareRight && start.mutate({ kind: 'range', base: compareLeft, head: compareRight })} disabled={!compareLeft || !compareRight || start.isPending}>Revisar comparação</Button></div>
    {taskId && <div className="mt-4 rounded-lg border border-primary/30 bg-primary/5 p-3" aria-live="polite"><p className="text-xs text-muted-foreground">Escopo: {scopeLabel} · tarefa {taskId.slice(0, 8)}</p>{task.isPending || task.data?.status === 'pending' || task.data?.status === 'running' ? <p role="status" className="mt-2 text-sm">Analisando o diff real com {agent === 'auto' ? 'o agente disponível' : agent}…</p> : task.data?.status === 'failed' ? <p role="alert" className="mt-2 text-sm text-destructive">A revisão falhou: {task.data.error ?? 'erro não informado.'}</p> : report.isPending ? <p role="status" className="mt-2 text-sm">Preparando achados…</p> : report.data ? <div className="mt-3"><p className="text-sm">{report.data.summary}</p><p className="mt-1 text-xs text-muted-foreground">{report.data.findings.length} achado(s) · agente {report.data.agent}{report.data.truncated ? ' · diff limitado para segurança' : ''}</p>{report.data.findings.length ? <ul className="mt-3 grid gap-3 lg:grid-cols-2">{report.data.findings.map((finding) => <li key={finding.id} className="rounded-lg border bg-background/50 p-3"><div className="flex flex-wrap items-center gap-2"><span className="rounded-full border px-2 py-0.5 text-[10px] uppercase tracking-wide">{finding.severity}</span><span className="text-[11px] text-muted-foreground">confiança {finding.confidence}</span>{finding.file && <code className="ml-auto text-[11px] text-primary">{finding.file}{finding.startLine ? `:${finding.startLine}` : ''}</code>}</div><h3 className="mt-2 text-sm font-medium">{finding.title}</h3><p className="mt-1 text-xs text-muted-foreground">{finding.description}</p>{finding.evidence && <pre className="mt-2 max-h-24 overflow-auto rounded border bg-muted/30 p-2 text-[11px] whitespace-pre-wrap">{finding.evidence}</pre>}{finding.suggestion && <p className="mt-2 text-xs"><span className="font-medium">Sugestão:</span> {finding.suggestion}</p>}{finding.file && scope.kind !== 'range' && <Button className="mt-2" size="sm" variant="ghost" onClick={() => onOpenDiff(finding.file as string, scope)}>Abrir diff do arquivo</Button>}{finding.patch && <details className="mt-2"><summary className="cursor-pointer text-xs text-primary">Pré-visualizar correção sugerida</summary><pre className="mt-2 max-h-48 overflow-auto rounded border bg-background p-2 text-[11px] whitespace-pre-wrap">{finding.patch}</pre><Button className="mt-2" size="sm" variant="outline" onClick={() => applyPatch.mutate({ findingId: finding.id, patch: finding.patch as string })} disabled={applyPatch.isPending}>Aplicar sugestão</Button></details>}</li>)}</ul> : <p className="mt-3 rounded border border-dashed p-3 text-xs text-muted-foreground">Nenhum problema foi encontrado no escopo analisado.</p>}</div> : null}</div>}
    {appliedFinding && <p role="status" className="mt-3 text-xs text-primary">Sugestão aplicada ao working tree. Revise as alterações antes de qualquer commit.</p>}
    {error instanceof Error && error.message !== 'cancelled' && <p role="alert" className="mt-3 text-xs text-destructive">{error.message}</p>}
    {applyPatch.error instanceof Error && applyPatch.error.message !== 'cancelled' && <p role="alert" className="mt-3 text-xs text-destructive">Não foi possível aplicar a sugestão: {applyPatch.error.message}</p>}
  </section>;
}

function SmartCommitPanel({ projectId }: { projectId: string }) {
  const queryClient = useQueryClient();
  const [agent, setAgent] = useState<SmartCommitAgent>('auto');
  const [taskId, setTaskId] = useState<string | null>(null);
  const [draftTaskId, setDraftTaskId] = useState<string | null>(null);
  const [draftOverride, setDraftOverride] = useState<SmartCommitReport['proposal'] | null>(null);
  const start = useMutation({
    mutationFn: () => window.neuralbridge.tasks.startSmartCommit({ projectId, agent }),
    onSuccess: ({ id }) => { setTaskId(id); setDraftTaskId(null); setDraftOverride(null); },
  });
  const task = useQuery({ queryKey: ['smart-commit-task', taskId], queryFn: () => window.neuralbridge.tasks.get(taskId as string), enabled: Boolean(taskId), refetchInterval: taskId ? 1000 : false });
  const report = useQuery({ queryKey: ['smart-commit-report', taskId], queryFn: () => window.neuralbridge.tasks.smartCommit(taskId as string), enabled: Boolean(taskId), refetchInterval: task.data?.status === 'completed' || task.data?.status === 'failed' || task.data?.status === 'cancelled' ? false : 1000 });
  const draft = draftTaskId === taskId ? draftOverride : report.data?.proposal ?? null;
  const commitMessage = draft ? [draft.subject.trim(), draft.body.trim()].filter(Boolean).join('\n\n') : '';
  const commitMessageTooLong = commitMessage.length > 500;
  const commit = useMutation({
    mutationFn: async () => {
      if (!draft) throw new Error('Gere uma proposta antes de criar o commit.');
      const message = [draft.subject.trim(), draft.body.trim()].filter(Boolean).join('\n\n');
      if (message.length > 500) throw new Error('A mensagem do commit precisa ter no máximo 500 caracteres.');
      if (!window.confirm('Criar um commit usando esta mensagem? A ação será explícita e não fará push nem abrirá PR.')) throw new Error('cancelled');
      const grant = await window.neuralbridge.projects.authorize(projectId, 'commit', { message });
      return window.neuralbridge.projects.commit(projectId, message, grant.token);
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['git-working-tree', projectId] });
      void queryClient.invalidateQueries({ queryKey: ['git-intelligence', projectId] });
      void queryClient.invalidateQueries({ queryKey: ['smart-commit-task', taskId] });
    },
  });
  const update = <K extends keyof SmartCommitReport['proposal']>(key: K, value: SmartCommitReport['proposal'][K]) => {
    if (!taskId) return;
    setDraftTaskId(taskId);
    setDraftOverride((current) => {
      const base = current ?? report.data?.proposal;
      return base ? { ...base, [key]: value } : null;
    });
  };
  const error = start.error ?? task.error ?? report.error ?? commit.error;
  return <section className="mx-auto mt-4 max-w-[1600px] rounded-xl border border-primary/30 bg-card p-4" aria-label="Smart Commit e PR Assistant">
    <div className="flex flex-wrap items-start justify-between gap-3"><div className="flex gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-lg bg-primary/10 text-primary"><Sparkles className="size-4" aria-hidden="true" /></span><div><h2 className="font-medium">Smart Commit &amp; PR Assistant</h2><p className="mt-1 max-w-3xl text-xs text-muted-foreground">Analisa somente o diff staged e prepara textos editáveis. Nenhum commit, push ou PR acontece ao gerar a proposta.</p></div></div><label className="text-xs text-muted-foreground">Agente<select aria-label="Agente do Smart Commit" className="ml-2 h-8 rounded-md border bg-background px-2 text-xs" value={agent} onChange={(event) => setAgent(event.target.value as SmartCommitAgent)} disabled={start.isPending}><option value="auto">Automático</option><option value="claude">Claude Code</option><option value="codex">Codex CLI</option></select></label></div>
    <div className="mt-4 flex flex-wrap items-center gap-2"><Button onClick={() => start.mutate()} disabled={start.isPending}>{start.isPending ? 'Preparando…' : 'Gerar proposta a partir do staged'}</Button>{taskId && <span className="text-xs text-muted-foreground">Tarefa {taskId.slice(0, 8)}</span>}</div>
    {taskId && <div className="mt-4 rounded-lg border bg-background/40 p-3" aria-live="polite">{task.isPending || task.data?.status === 'pending' || task.data?.status === 'running' ? <p role="status" className="text-sm">Lendo diff staged com {agent === 'auto' ? 'o agente disponível' : agent}…</p> : task.data?.status === 'failed' ? <p role="alert" className="text-sm text-destructive">A proposta falhou: {task.data.error ?? 'erro não informado.'}</p> : report.isPending ? <p role="status" className="text-sm">Validando proposta…</p> : draft ? <div className="grid gap-4 lg:grid-cols-2"><div className="space-y-3"><div><label className="text-xs font-medium" htmlFor="smart-commit-subject">Subject Conventional Commit</label><input id="smart-commit-subject" className="mt-1 h-9 w-full rounded-md border bg-background px-2 text-sm" value={draft.subject} onChange={(event) => update('subject', event.target.value)} /></div><div><label className="text-xs font-medium" htmlFor="smart-commit-body">Corpo do commit</label><textarea id="smart-commit-body" className="mt-1 min-h-24 w-full rounded-md border bg-background p-2 text-sm" value={draft.body} onChange={(event) => update('body', event.target.value)} /></div><div className="flex flex-wrap items-center gap-2"><Button onClick={() => commit.mutate()} disabled={commit.isPending || !draft.subject.trim() || commitMessageTooLong}>Criar commit explicitamente</Button><span className={`text-[11px] ${commitMessageTooLong ? 'text-destructive' : 'text-muted-foreground'}`}>{commitMessage.length}/500 caracteres</span></div>{commitMessageTooLong && <p role="alert" className="text-xs text-destructive">A mensagem excede o limite de 500 caracteres do commit. Edite o subject ou o corpo para continuar.</p>}</div><div className="space-y-3"><div><label className="text-xs font-medium" htmlFor="smart-pr-title">Título da PR</label><input id="smart-pr-title" className="mt-1 h-9 w-full rounded-md border bg-background px-2 text-sm" value={draft.prTitle} onChange={(event) => update('prTitle', event.target.value)} /></div><div><label className="text-xs font-medium" htmlFor="smart-pr-body">Descrição da PR</label><textarea id="smart-pr-body" className="mt-1 min-h-24 w-full rounded-md border bg-background p-2 text-sm" value={draft.prBody} onChange={(event) => update('prBody', event.target.value)} /></div><details className="rounded-md border p-2"><summary className="cursor-pointer text-xs text-primary">Changelog e impacto documental</summary><label className="mt-2 block text-xs" htmlFor="smart-changelog">Changelog<textarea id="smart-changelog" className="mt-1 min-h-16 w-full rounded-md border bg-background p-2 text-xs" value={draft.changelog} onChange={(event) => update('changelog', event.target.value)} /></label><label className="mt-2 block text-xs" htmlFor="smart-doc-impact">Impacto em documentação<textarea id="smart-doc-impact" className="mt-1 min-h-16 w-full rounded-md border bg-background p-2 text-xs" value={draft.documentationImpact} onChange={(event) => update('documentationImpact', event.target.value)} /></label></details><div><p className="text-xs font-medium">Checklist sugerido</p><ul className="mt-1 list-disc pl-4 text-xs text-muted-foreground">{draft.checklist.length ? draft.checklist.map((item) => <li key={item}>{item}</li>) : <li>Nenhum item sugerido.</li>}</ul></div></div></div> : <p className="text-sm text-muted-foreground">Nenhuma proposta disponível.</p>}</div>}
    {commit.isSuccess && <p role="status" className="mt-3 text-xs text-primary">Commit criado. Nenhum push ou PR foi executado.</p>}
    {error instanceof Error && error.message !== 'cancelled' && <p role="alert" className="mt-3 text-xs text-destructive">{error.message}</p>}
  </section>;
}

export function GitIntelligencePage() {
  const projects = useProjectList();
  const queryClient = useQueryClient();
  const [projectId, setProjectId] = useState('');
  const [query, setQuery] = useState('');
  const [selectedHash, setSelectedHash] = useState<string | null>(null);
  const [cursor, setCursor] = useState<string | undefined>();
  const [pages, setPages] = useState<GitHistoryCommit[]>([]);
  const [compact, setCompact] = useState(() => window.localStorage.getItem('neuralbridge.git-graph-density') !== 'expanded');
  const [compareLeft, setCompareLeft] = useState('');
  const [compareRight, setCompareRight] = useState('');
  const [compareMode, setCompareMode] = useState<'direct' | 'merge-base'>('direct');
  const [diffOpen, setDiffOpen] = useState(false);
  const [diffPath, setDiffPath] = useState<string | undefined>();
  const [diffCommit, setDiffCommit] = useState<string | null | undefined>();
  const [activeTab, setActiveTab] = useState<GitWorkspaceTab>('overview');
  const history = useQuery({ queryKey: ['git-intelligence', projectId, cursor], queryFn: () => window.neuralbridge.projects.history(projectId, cursor), enabled: projectId !== '' });
  useEffect(() => {
    if (!history.data?.isRepo) return;
    startTransition(() => setPages((current) => cursor ? [...current, ...history.data.commits.filter((commit) => !current.some((item) => item.hash === commit.hash))] : history.data.commits));
  }, [cursor, history.data]);
  const commits = useMemo(() => {
    const needle = query.trim().toLocaleLowerCase();
    return pages.filter((commit) => !needle || [commit.hash, commit.subject, commit.author, ...commit.files.map((file) => file.path)].some((value) => value.toLocaleLowerCase().includes(needle)));
  }, [pages, query]);
  const selected = commits.find((commit) => commit.hash === selectedHash) ?? commits[0] ?? null;
  const diff = useQuery({ queryKey: ['git-intelligence-diff', projectId, selected?.hash, diffCommit, diffPath], queryFn: () => window.neuralbridge.projects.diff(projectId, diffPath, diffCommit === null ? undefined : diffCommit ?? selected?.hash ?? undefined), enabled: diffOpen && Boolean(projectId) });
  const comparison = useQuery({ queryKey: ['git-intelligence-compare', projectId, compareLeft, compareRight, compareMode], queryFn: () => window.neuralbridge.projects.compare(projectId, compareLeft, compareRight, compareMode), enabled: Boolean(projectId && compareLeft && compareRight) });
  const workingTree = useQuery({ queryKey: ['git-working-tree', projectId], queryFn: () => window.neuralbridge.projects.workingTree(projectId), enabled: Boolean(projectId && history.data?.isRepo) });
  const stage = useMutation({ mutationFn: async (paths: string[]) => { if (!window.confirm(`Preparar ${paths.length} arquivo(s) para commit?`)) throw new Error('cancelled'); const grant = await window.neuralbridge.projects.authorize(projectId, 'stage', { paths }); return window.neuralbridge.projects.stage(projectId, paths, grant.token); }, onSuccess: () => void queryClient.invalidateQueries({ queryKey: ['git-working-tree', projectId] }) });
  const unstage = useMutation({ mutationFn: async (paths: string[]) => { if (!window.confirm(`Retirar ${paths.length} arquivo(s) da área staged?`)) throw new Error('cancelled'); const grant = await window.neuralbridge.projects.authorize(projectId, 'unstage', { paths }); return window.neuralbridge.projects.unstage(projectId, paths, grant.token); }, onSuccess: () => void queryClient.invalidateQueries({ queryKey: ['git-working-tree', projectId] }) });
  const branches = history.data?.branches ?? [];
  const refs = history.data?.refs ?? [];
  const remoteRefs = refs.filter((ref) => ref.kind === 'remote');
  const tags = refs.filter((ref) => ref.kind === 'tag');
  return <main className="flex h-full min-h-0 flex-col bg-background text-foreground">
    <header className="mx-auto flex w-full max-w-[1600px] shrink-0 flex-wrap items-center justify-between gap-4 border-b border-border px-5 pt-5 pb-5 sm:px-7"><div><h1 className="text-[26px] leading-tight font-light tracking-[0.005em] text-foreground">Git Intelligence</h1><p className="mt-1 text-sm text-muted-foreground">Explore o histórico real dos seus projetos, em modo somente leitura.</p></div><div className="flex flex-wrap gap-2"><select aria-label="Selecionar projeto" className="h-9 min-w-56 rounded-md border bg-card px-3 text-sm" value={projectId} onChange={(event) => { setProjectId(event.target.value); setSelectedHash(null); setCursor(undefined); setPages([]); setCompareLeft(''); setCompareRight(''); setCompareMode('direct'); setActiveTab('overview'); }}><option value="">Selecione um projeto</option>{projects.data?.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select><Button variant="outline" onClick={() => void history.refetch()} disabled={!projectId || history.isFetching}>Atualizar</Button></div></header>
    {projectId && history.data?.isRepo && <div className="mx-auto flex w-full max-w-[1600px] shrink-0 gap-1 overflow-x-auto border-b border-border px-5 pt-3 sm:px-7" role="tablist" aria-label="Seções do Git Intelligence">
      {GIT_WORKSPACE_TABS.map((tab) => <button key={tab.id} type="button" role="tab" aria-selected={activeTab === tab.id} aria-controls={`git-tabpanel-${tab.id}`} className={`shrink-0 border-b-2 px-3 py-2 text-sm outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring ${activeTab === tab.id ? 'border-primary text-foreground' : 'border-transparent text-muted-foreground hover:text-foreground'}`} onClick={() => setActiveTab(tab.id)}>{tab.label}</button>)}
    </div>}
    <div className="flex min-h-0 flex-1 flex-col overflow-hidden px-5 pb-5 sm:px-7 sm:pb-7">
    {!projectId ? <section className="mx-auto mt-12 max-w-xl rounded-xl border border-dashed p-10 text-center"><GitBranch className="mx-auto size-10 text-muted-foreground" /><h2 className="mt-4 text-lg font-medium">Selecione um projeto Git</h2><p className="mt-2 text-sm text-muted-foreground">O grafo consulta diretamente o repositório local autorizado e não executa operações de escrita.</p></section> : history.isPending ? <p role="status" className="mt-8 text-muted-foreground">Carregando histórico Git…</p> : history.isError ? <p role="alert" className="mt-8 text-destructive">Não foi possível ler o histórico Git. Tente atualizar o projeto.</p> : !history.data?.isRepo ? <p role="alert" className="mt-8 text-warning">A pasta selecionada não é um repositório Git válido ou está indisponível.</p> : activeTab === 'overview' ? <div id="git-tabpanel-overview" role="tabpanel" tabIndex={0} className="mx-auto mt-5 grid min-h-0 min-w-0 flex-1 max-w-[1600px] gap-4 overflow-hidden xl:grid-cols-[220px_minmax(0,1fr)_360px]">
      <aside className="min-h-0 space-y-5 overflow-y-auto sg-panel rounded-xl p-4"><div><h2 className="font-medium">Referências</h2><ul className="mt-3 space-y-2 text-sm">{branches.map((branch) => <li key={branch.name} className="flex items-center gap-2 text-muted-foreground"><GitBranch className="size-3.5 text-primary" /><span className="min-w-0 truncate">{branch.name}</span>{history.data.head === branch.name && <span className="ml-auto rounded-full border border-primary/40 px-1.5 py-0.5 text-[10px] text-primary">HEAD</span>}</li>)}{remoteRefs.map((ref) => <li key={ref.name} className="flex items-center gap-2 text-muted-foreground"><GitBranch className="size-3.5 opacity-60" /><span className="min-w-0 truncate">{ref.name}</span></li>)}{tags.map((ref) => <li key={ref.name} className="flex items-center gap-2 text-muted-foreground"><Tag className="size-3.5 text-warning" /><span className="min-w-0 truncate">{ref.name}</span></li>)}</ul>{!refs.length && <p className="mt-3 text-xs text-muted-foreground">Nenhuma referência encontrada.</p>}</div><div><h2 className="font-medium">Working tree</h2>{workingTree.isPending ? <p role="status" className="mt-2 text-xs text-muted-foreground">Lendo alterações…</p> : workingTree.data?.length ? <ul className="mt-2 space-y-2 text-xs">{workingTree.data.map((file) => <li key={file.path} className="space-y-1"><span className="block truncate" title={file.path}>{file.status} · {file.path}</span><div className="flex gap-1">{(!file.staged || file.status === 'conflict') && <Button size="sm" variant="outline" className="h-7 px-2 text-[11px]" onClick={() => stage.mutate([file.path])} disabled={stage.isPending}>Stage</Button>}{file.staged && file.status !== 'conflict' && <Button size="sm" variant="outline" className="h-7 px-2 text-[11px]" onClick={() => unstage.mutate([file.path])} disabled={unstage.isPending}>Unstage</Button>}</div></li>)}</ul> : <p className="mt-2 text-xs text-muted-foreground">Working tree limpa.</p>}{[stage.error, unstage.error].map((failure) => (failure instanceof Error && failure.message !== 'cancelled' ? <p key={failure.message} role="alert" className="mt-2 text-xs text-destructive">Não foi possível alterar o stage: {failure.message}</p> : null))}</div><div><h2 className="font-medium">Filtros</h2><p className="mt-2 text-xs text-muted-foreground">{history.data.commits.length} commits carregados · limite incremental de 200</p></div></aside>
      <section className="min-h-0 min-w-0 overflow-hidden sg-panel rounded-xl p-4"><div className="mb-4 flex items-center gap-2"><Search className="size-4 text-muted-foreground" /><input aria-label="Buscar commits" className="h-9 min-w-0 flex-1 rounded-md border bg-background px-3 text-sm" placeholder="Hash, mensagem, autor ou arquivo" value={query} onChange={(event) => setQuery(event.target.value)} /><Button variant="outline" size="sm" aria-pressed={compact} onClick={() => { const next = !compact; setCompact(next); window.localStorage.setItem('neuralbridge.git-graph-density', next ? 'compact' : 'expanded'); }}>{compact ? 'Expandido' : 'Compacto'}</Button></div>{commits.length ? <CommitGraph commits={commits} compact={compact} selected={selected?.hash ?? null} onSelect={setSelectedHash ? (commit) => setSelectedHash(commit.hash) : () => undefined} /> : <p className="p-6 text-center text-sm text-muted-foreground">{pages.length === 0 ? 'Este repositório ainda não possui commits.' : 'Nenhum commit corresponde à busca.'}</p>}{history.data.nextCursor && <Button className="mt-4 w-full" variant="outline" onClick={() => setCursor(history.data.nextCursor ?? undefined)} disabled={history.isFetching}>Carregar commits anteriores</Button>}</section>
      <aside className="min-h-0 space-y-4 overflow-y-auto sg-panel rounded-xl p-4"><h2 className="font-medium">Detalhes do commit</h2>{selected ? <><div><code className="text-xs text-primary">{selected.hash}</code><h3 className="mt-2 font-medium">{selected.subject}</h3><p className="mt-1 text-xs text-muted-foreground">{selected.author} · {new Date(selected.date).toLocaleString()}</p></div><div><h3 className="text-sm font-medium">Arquivos alterados</h3><ul className="mt-2 max-h-40 space-y-1 overflow-y-auto text-xs">{selected.files.map((file) => <li key={`${file.path}-${file.status}`} className="flex gap-2"><span className="font-mono text-primary">{file.status[0]?.toUpperCase()}</span><span className="truncate">{file.path}</span></li>)}</ul></div><Button variant="outline" size="sm" onClick={() => void diff.refetch()}>Ver diff</Button>{diff.data && <pre className="max-h-72 overflow-auto rounded border bg-background p-2 text-[11px] whitespace-pre-wrap">{diff.data.text}</pre>}<p className="border-t pt-3 text-xs text-muted-foreground">Relações com tarefas e memórias estão disponíveis no histórico Git do projeto.</p></> : <p className="text-sm text-muted-foreground">Selecione um commit no grafo.</p>}<div className="border-t pt-4"><h2 className="font-medium">Comparar referências</h2><div className="mt-2 grid gap-2"><select aria-label="Referência inicial" className="h-9 rounded-md border bg-background px-2 text-sm" value={compareLeft} onChange={(event) => setCompareLeft(event.target.value)}><option value="">Ref inicial</option>{refs.map((ref) => <option key={`left-${ref.kind}-${ref.name}`} value={ref.name}>{ref.name}</option>)}{commits.map((commit) => <option key={`left-commit-${commit.hash}`} value={commit.hash}>{commit.hash.slice(0, 8)} · {commit.subject}</option>)}</select><select aria-label="Referência final" className="h-9 rounded-md border bg-background px-2 text-sm" value={compareRight} onChange={(event) => setCompareRight(event.target.value)}><option value="">Ref final</option>{refs.map((ref) => <option key={`right-${ref.kind}-${ref.name}`} value={ref.name}>{ref.name}</option>)}{commits.map((commit) => <option key={`right-commit-${commit.hash}`} value={commit.hash}>{commit.hash.slice(0, 8)} · {commit.subject}</option>)}</select><select aria-label="Modo de comparação" className="h-9 rounded-md border bg-background px-2 text-sm" value={compareMode} onChange={(event) => setCompareMode(event.target.value as 'direct' | 'merge-base')}><option value="direct">Diferença direta</option><option value="merge-base">Desde merge-base</option></select></div>{comparison.isError && <p role="alert" className="mt-2 text-xs text-destructive">Não foi possível comparar estas referências.</p>}{comparison.data && <div className="mt-3 space-y-2 text-xs"><p className="text-muted-foreground">+{comparison.data.added} linhas · −{comparison.data.removed} linhas{comparison.data.mergeBase ? ` · base ${comparison.data.mergeBase.slice(0, 8)}` : ''}</p><ul className="max-h-40 space-y-1 overflow-auto">{comparison.data.files.map((file) => <li key={`${file.path}-${file.status}`} className="flex justify-between gap-2"><span className="truncate">{file.status} · {file.path}</span><span className="shrink-0 text-muted-foreground">+{file.added}/−{file.removed}</span></li>)}</ul></div>}</div></aside>
    </div> : activeTab === 'automations' ? <div id="git-tabpanel-automations" role="tabpanel" tabIndex={0} className="min-h-0 flex-1 overflow-y-auto"><AutomationsPanel projectId={projectId} commit={selected?.hash ?? null} branches={branches.map((branch) => branch.name)} /></div> : activeTab === 'review' ? <div id="git-tabpanel-review" role="tabpanel" tabIndex={0} className="min-h-0 flex-1 overflow-y-auto"><GitReviewPanel projectId={projectId} selectedCommit={selected?.hash ?? null} compareLeft={compareLeft} compareRight={compareRight} onOpenDiff={(path, reviewScope) => { setDiffPath(path); setDiffCommit(reviewScope.kind === 'commit' ? reviewScope.commit : null); setDiffOpen(true); }} /></div> : activeTab === 'commit' ? <div id="git-tabpanel-commit" role="tabpanel" tabIndex={0} className="min-h-0 flex-1 overflow-y-auto"><SmartCommitPanel projectId={projectId} /></div> : <div id="git-tabpanel-operations" role="tabpanel" tabIndex={0} className="min-h-0 flex-1 overflow-y-auto"><GitOperationsPanel projectId={projectId} workingTree={workingTree.data ?? []} selectedCommit={selected?.hash ?? null} selectedParents={selected?.parents.length ?? 0} onRefresh={() => { void history.refetch(); }} /></div>}
    {diffOpen && <div role="dialog" aria-modal="true" aria-label="Diff do código" className="mx-auto mt-4 max-w-[1600px] sg-panel rounded-xl p-4"><div className="flex items-center justify-between gap-3"><h2 className="font-medium">Diff{diffPath ? ` · ${diffPath}` : ''}</h2><Button size="sm" variant="outline" onClick={() => setDiffOpen(false)}>Fechar</Button></div>{diff.isPending && <p role="status" className="mt-3 text-sm text-muted-foreground">Carregando diff…</p>}{diff.isError && <p role="alert" className="mt-3 text-sm text-destructive">Não foi possível carregar o diff.</p>}{diff.data && <pre className="mt-3 max-h-[60vh] overflow-auto rounded border bg-background p-3 text-xs whitespace-pre-wrap">{diff.data.text}</pre>}</div>}
    </div>
  </main>;
}
